-- MT2009_PLUS_237_GLOBAL_MODE_V1: refining as on the global server (M2_BONUS_MODE=global only). GENERATED by
-- tools/globalmode/gen_globalmode_2x.py from tools/refineglobal/ulepszanie_global.json (the owner's upgrade sheet,
-- read 16.10.2026; the Yohara line's MT2009_PLUS_REFINE_GLOBAL_V1) - do not edit, rerun it.
-- 4003 steps with a chance, 438 recipes (refine_proto 40000-40437), 195 steps without a chance and 49 Seon-Pyeong steps
-- (ids 39900-39999 on Yohara: the 2.x engine has no IsEliteRefine) left out. Fills world.item_proto_refine_global
-- (vnum -> the global next item and recipe): an item whose next item is the sheet's (or none, for a "+9 -> next
-- item" step), whose result and every material exist. apply.sh writes it into item_proto (and keeps the mt2009
-- values in world.item_proto_refine_mt2009). Idempotent.
SET NAMES utf8mb4;
USE world;
ON DUPLICATE KEY UPDATE vnum0=VALUES(vnum0), count0=VALUES(count0), vnum1=VALUES(vnum1), count1=VALUES(count1), vnum2=VALUES(vnum2), count2=VALUES(count2), vnum3=VALUES(vnum3), count3=VALUES(count3), vnum4=VALUES(vnum4), count4=VALUES(count4), cost=VALUES(cost), src_vnum=0, result_vnum=0, prob=VALUES(prob);
DROP TEMPORARY TABLE IF EXISTS tmp_refine_global;
CREATE TEMPORARY TABLE tmp_refine_global (src INT UNSIGNED NOT NULL PRIMARY KEY, res INT UNSIGNED NOT NULL, rid INT UNSIGNED NOT NULL, tr TINYINT NOT NULL);
-- a step whose material is not in our item_proto stays as it is
DROP TEMPORARY TABLE IF EXISTS tmp_refine_global_mat;
CREATE TEMPORARY TABLE tmp_refine_global_mat (rid INT UNSIGNED NOT NULL, vnum INT UNSIGNED NOT NULL, PRIMARY KEY (rid, vnum));
DELETE s FROM tmp_refine_global s JOIN tmp_refine_global_mat m ON m.rid = s.rid LEFT JOIN world.item_proto p ON p.vnum = m.vnum WHERE p.vnum IS NULL;
CREATE TABLE IF NOT EXISTS world.item_proto_refine_global (vnum INT UNSIGNED NOT NULL PRIMARY KEY, refined_vnum INT UNSIGNED NOT NULL, refine_set INT UNSIGNED NOT NULL) ENGINE=InnoDB;
START TRANSACTION;
DELETE FROM world.item_proto_refine_global;
COMMIT;
DROP TEMPORARY TABLE tmp_refine_global_mat;
DROP TEMPORARY TABLE tmp_refine_global;
