INSERT INTO world.item_proto_refine_global (vnum, refined_vnum, refine_set) SELECT i.vnum, s.res, s.rid FROM world.item_proto i JOIN tmp_refine_global s ON s.src = i.vnum JOIN world.item_proto r ON r.vnum = s.res WHERE i.refined_vnum = s.res OR (s.tr = 1 AND i.refined_vnum = 0);
